 const load=async()=>{if(!clipId)return;const c=await api('/clips/'+clipId);setClip(c);setPlan(c.plan);setTitle(c.title);setDirty(false);setPreview(!!c.media_url)};
 useEffect(()=>{setClip(null);setPlan(null);load().catch((e:any)=>toast(e.message,true))},[clipId]);
