function QueuePage({jobs,act,pending}:any){const [filter,setFilter]=useState('all'),[logsId,setLogsId]=useState('');const shown=jobs.filter((j:Job)=>filter==='all'||(filter==='active'?['Running','Queued','Paused'].includes(j.status):j.status===filter));const active=jobs.filter((j:Job)=>['Running','Queued','Paused'].includes(j.status));const progress=active.length?active.reduce((n:number,j:Job)=>n+j.progress,0)/active.length:0;const control=(j:Job,a:string)=>act(()=>post(`/jobs/${j.id}/${a}`));return <><PageTitle title={tr("Очередь обработки")} subtitle={tr("{0} незавершённых задач · этапы восстанавливаются из SQLite",[active.length])} action={<div className="button-row"><Button disabled={pending||!jobs.some((j:Job)=>['Running','Queued'].includes(j.status))} onClick={()=>act(()=>Promise.all(jobs.filter((j:Job)=>['Running','Queued'].includes(j.status)).map((j:Job)=>post(`/jobs/${j.id}/pause`))))}><Pause size={14}/>{tr("Пауза")}</Button><Button disabled={pending||!jobs.some((j:Job)=>j.status==='Paused')} onClick={()=>act(()=>Promise.all(jobs.filter((j:Job)=>j.status==='Paused').map((j:Job)=>post(`/jobs/${j.id}/resume`))))}><Play size={14}/>{tr("Продолжить")}</Button><Button disabled={pending||!jobs.some((j:Job)=>j.status==='Failed')} onClick={()=>act(()=>Promise.all(jobs.filter((j:Job)=>j.status==='Failed').map((j:Job)=>post(`/jobs/${j.id}/retry`))))}><RotateCcw size={14}/>{tr("Повтор ошибок")}</Button></div>}/>{active.length>0&&<div className="overall-progress panel"><div className="spread"><span>{tr("Прогресс незавершённых задач")}</span><strong>{Math.round(progress)}%</strong></div><div className="progress"><i style={{width:progress+'%'}}/></div></div>}<div className="toolbar"><div className="tabs">{[['all',tr("Все задачи")],['active',tr("В работе")],['Completed',tr("Завершённые")],['Failed',tr("Ошибки")]].map(([id,label])=><button key={id} className={filter===id?'selected':''} onClick={()=>setFilter(id)}>{label}</button>)}</div><span className="muted small-text">Whisper 1 · AI 1 · FFmpeg 1</span></div>{shown.length?<div className="job-list">{shown.map((j:Job)=><article className="job-row" key={j.id}><div className="job-main"><div className="job-type">{j.kind==='render'?<Clapperboard size={20}/>:['download','export'].includes(j.kind)?<Download size={20}/>:<ScanLine size={20}/>}</div><div><strong>{j.clip_title||j.source_name}</strong><small>{j.kind==='render'?tr("Создание Reel"):j.kind==='download'?tr("Скачивание YouTube"):j.kind==='export'?tr("ZIP с готовыми роликами"):tr("Анализ исходника")} · {j.id.slice(0,8)}</small>{j.output&&<small className="job-file" title={j.output.path}>{tr("Файл:")} {j.output.filename}</small>}{j.error&&<p className="job-error">{j.error}</p>}</div></div><div className="job-progress"><div className="spread"><span>{status(j.stage)}</span><small>{Math.round(j.progress)}%</small></div><div className="progress"><i style={{width:j.progress+'%'}}/></div>{j.kind==='download'&&j.checkpoints?.download_progress?.downloaded_bytes>0&&<small className="muted">{bytes(j.checkpoints.download_progress.downloaded_bytes)}{j.checkpoints.download_progress.total_bytes?' / '+bytes(j.checkpoints.download_progress.total_bytes):''}{j.checkpoints.download_progress.speed?' · '+bytes(j.checkpoints.download_progress.speed)+tr("/с"):''}</small>}</div><Badge value={j.status}/><div className="job-actions">{j.output&&<Button size="sm" disabled={pending} title={j.output.path} onClick={()=>act(()=>post(`/jobs/${j.id}/reveal`),REVEALED())}><FolderOpen size={14}/>{REVEAL_LABEL()}</Button>}{j.output&&j.kind==='render'&&<a className="button secondary small" href={j.output.download_url} download><Download size={13}/>{tr("Скачать MP4")}</a>}{j.kind==='export'&&j.status==='Completed'&&j.checkpoints?.download_url&&<a className="button secondary small" href={j.checkpoints.download_url} download><Download size={13}/>{tr("Скачать ZIP")}</a>}{j.kind==='download'&&j.status==='Failed'&&<Button size="sm" onClick={()=>{sessionStorage.setItem('factory-settings-section','youtube');location.hash='settings'}}>{tr("Аккаунт YouTube")}</Button>}{j.kind==='download'&&j.status==='Completed'&&j.source_id&&<Button size="sm" onClick={()=>{location.hash='sources'}}>{tr("Исходник")}<ArrowUpRight size={13}/></Button>}{['Queued','Running'].includes(j.status)&&<Button size="icon" title={tr("Пауза")} aria-label={tr("Пауза")} disabled={pending} onClick={()=>control(j,'pause')}><Pause size={14}/></Button>}{j.status==='Paused'&&<Button size="icon" title={tr("Продолжить")} aria-label={tr("Продолжить")} disabled={pending} onClick={()=>control(j,'resume')}><Play size={14}/></Button>}{['Failed','Cancelled'].includes(j.status)&&<Button size="icon" title={tr("Повторить")} aria-label={tr("Повторить")} disabled={pending} onClick={()=>control(j,'retry')}><RotateCcw size={14}/></Button>}{['Queued','Running','Paused'].includes(j.status)&&<Button size="icon" title={tr("Отменить")} aria-label={tr("Отменить")} disabled={pending} onClick={()=>control(j,'cancel')}><X size={15}/></Button>}<Button size="sm" variant="ghost" onClick={()=>setLogsId(logsId===j.id?'':j.id)}>{tr("Лог")}<ChevronDown size={13}/></Button></div>{logsId===j.id&&<pre className="job-log">{j.logs.map(l=>`${new Date(l.time*1000).toLocaleTimeString()}  ${l.message}`).join('\n')||tr("Задача ещё не запускалась")}</pre>}</article>)}</div>:<Empty title={tr("Задач в этой очереди нет")} icon={Layers}><p>{tr("Анализ и рендер запускаются из исходников и редактора.")}</p></Empty>}</>}

function SettingsPage({config,doctor,dash,act,toast}:any){const [section,setSection]=useState(()=>{const selected=sessionStorage.getItem('factory-settings-section');sessionStorage.removeItem('factory-settings-section');const requested=new URLSearchParams(location.search).get('settings');return requested&&['ai','voice','pilot','export','youtube','publish','storage','system','language'].includes(requested)?requested:selected||'ai'}),[values,setValues]=useState<any>(config.values),[keys,setKeys]=useState<Record<string,string>>({}),[dirty,setDirty]=useState(false);const change=(k:string,v:any)=>{setValues({...values,[k]:v});setDirty(true)};useEffect(()=>{if(!dirty)setValues(config.values)},[config.values,dirty]);const save=async()=>{const r=await act(()=>api('/settings',{method:'PUT',body:JSON.stringify({values,...keys})}),tr("Настройки сохранены"));if(r){setKeys({});setDirty(false)}return r};return <><PageTitle title={tr("Настройки")} subtitle={tr("Провайдеры, экспорт, расходы и локальное хранилище.")} action={<Button variant="default" disabled={!dirty&&!Object.keys(keys).length} onClick={save}>{tr("Сохранить изменения")}</Button>}/><div className="tabs settings-tabs">{[['ai',tr("AI и модели")],['voice',tr("Озвучка")],['pilot',tr("AI-проба")],['export',tr("Экспорт")],['youtube',tr("Скачивание YouTube")],['publish',tr("Публикации")],['storage',tr("Хранилище")],['system',tr("Диагностика")],['language',tr("Язык")]].map(([id,label])=><button key={id} className={section===id?'selected':''} onClick={()=>setSection(id)}>{label}</button>)}</div>{section==='language'?<LanguageSettings/>:section==='ai'?<AISettings config={config} values={values} change={change} keys={keys} setKey={(k,v)=>setKeys(previous=>{const next={...previous};if(v)next[k]=v;else delete next[k];return next})} save={async()=>dirty||Object.keys(keys).length?save():config}/>:section==='voice'?<VoiceSettings config={config} values={values} change={change} keys={keys} setKey={(k,v)=>setKeys(previous=>{const next={...previous};if(v)next[k]=v;else delete next[k];return next})} save={async()=>dirty||Object.keys(keys).length?save():config}/>:section==='pilot'?<AuthorPilotSettings config={config} save={async()=>dirty||Object.keys(keys).length?save():config}/>:section==='export'?<div className="settings-row"><div><h2>{tr("Новые клипы")}</h2><p>{tr("Эти значения применяются к новым монтажным планам. В Clip Studio у каждого клипа свои настройки.")}</p></div><div className="panel settings-form"><div className="form-grid"><Field label={tr("Формат")}><select value={values.aspect} onChange={e=>change('aspect',e.target.value)}>{['9:16','1:1','4:5','16:9'].map(a=><option key={a}>{a}</option>)}</select></Field><Field label={tr("Частота кадров")}><select value={values.fps} onChange={e=>change('fps',+e.target.value)}><option value={30}>30 fps</option><option value={60}>60 fps</option></select></Field></div><Field label={tr("Субтитры")}><select value={values.subtitle_preset} onChange={e=>change('subtitle_preset',e.target.value)}>{Object.keys(config.presets).map(p=><option key={p}>{p}</option>)}</select></Field><Field label={tr("Кадрирование")}><select value={values.crop_mode} onChange={e=>change('crop_mode',e.target.value)}>{[['blur','Blurred Background'],['smart','Smart Face Crop'],['center','Center Crop'],['split','Split Layout'],['manual','Manual']].map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></Field><Field label={tr("Кодировщик")}><select value={values.encoder} onChange={e=>change('encoder',e.target.value)}><option value="auto">Auto · VideoToolbox → libx264</option><option value="software">libx264</option><option value="videotoolbox">VideoToolbox</option></select></Field></div></div>:section==='publish'?<PublishingSettings values={values} change={change}/>:section==='youtube'?<div className="settings-row"><div><h2>{tr("Вход и скачивание")}</h2><p>{tr("Подключите аккаунт, чтобы скачивать доступные ему ролики, включая видео с подтверждением возраста. Сессия используется yt-dlp локально и не отправляется AI-провайдеру.")}</p></div><YouTubeAccount/></div>:section==='storage'?<><div className="settings-row"><div><h2>{tr("Локальные файлы")}</h2><p>{tr("Свободно")} {bytes(dash.disk.free)} {tr("из")} {bytes(dash.disk.total)}{tr(". Оригиналы не удаляются автоматически.")}</p></div><div className="panel settings-form">{doctor?.paths&&Object.entries(doctor.paths).map(([k,v]:any)=><Field key={k} label={k}><code className="path-code">{v}</code></Field>)}<Field label={tr("Минимальный запас диска, МБ")}><input type="number" min={128} value={values.min_free_mb} onChange={e=>change('min_free_mb',+e.target.value)}/></Field><Field label={tr("Лимит одного файла, МБ")}><input type="number" min={1} max={100000} value={values.max_upload_mb} onChange={e=>change('max_upload_mb',+e.target.value)}/></Field></div></div><div className="settings-row"><div><h2>{tr("Временный кэш")}</h2><p>{tr("Очистка аудио, превью и временных кадров. Транскрипции, AI-ответы, проекты и готовые ролики сохраняются.")}</p></div><div className="panel settings-form"><Button onClick={async()=>{if(confirm(tr("Удалить временные файлы? Оригиналы, AI-кэш, проекты и рендеры сохранятся."))){const r=await act(()=>post('/storage/clear-cache'));if(r)toast(tr("Освобождено {0}",[bytes(r.removed_bytes)]))}}}><Trash2 size={15}/>{tr("Очистить временный кэш")}</Button></div></div></>:<div className="settings-row"><div><h2>{tr("Локальная обработка")}</h2><p>{tr("Один процесс Whisper, один облачный анализ и один FFmpeg одновременно. Число ограничено для памяти и температуры.")}</p><p>{tr("Реальный Gemini без подключённого ключа не проверен.")}</p></div><div className="panel settings-form">{doctor?Object.entries(doctor).filter(([k,v])=>typeof v==='string'||typeof v==='number'||typeof v==='boolean').map(([k,v])=><div className="diagnostic-row" key={k}><span>{k}</span><code>{String(v)}</code></div>):<p>{tr("Диагностика недоступна")}</p>}<h3>{tr("Границы автоматизации")}</h3>{doctor?.limits?.map((l:string,i:number)=><p className="muted" key={i}>{l}</p>)}</div></div>}</>}

initLang().then(()=>createRoot(document.getElementById('root')!).render(<App/>));
